WITH cleaned AS (SELECT *, ROUND(quantity * 100, 2) AS quantity_scaled, ROUND(quantity, 1) AS quantity_rounded FROM order_items WHERE order_id IN (5, 12, 15)) SELECT id, order_id, product_id, unit_price, quantity_scaled, quantity_rounded, AVG(quantity_rounded) OVER w_recent AS last4_avg_quantity_rounded, COUNT(quantity_rounded) OVER w_recent AS last4_count_quantity_rounded, MIN(quantity_rounded) OVER w_recent AS last4_min_quantity_rounded FROM cleaned WINDOW w_recent AS (PARTITION BY order_id, product_id ORDER BY quantity_scaled, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW);
